export type Cell = [number, number];

export function nextGeneration(cells: Cell[]): Cell[] {
  return [];
}

import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  // Simplest case: empty grid
  it("empty grid stays empty -- []", () => {
    expect(nextGeneration([])).toEqual([]);
  });

  // Rule 1 - Underpopulation
  it.todo("single live cell dies from underpopulation -- [(0,0)] -> []");
  it.todo("two adjacent live cells both die from underpopulation -- [(0,1),(1,1)] -> []");

  // Still life - Block (each cell has 3 neighbors -> survives, no new births)
  it.todo("block still life is unchanged -- [(0,0),(1,0),(0,1),(1,1)] stays the same");

  // Rule 2 - Survival (center cell with 3 neighbors survives)
  it.todo("Rule 2 example: center cell (1,1) survives with 3 neighbors");

  // Rule 4 - Reproduction (dead cell with exactly 3 neighbors becomes alive)
  it.todo("Rule 4 example: dead cell (1,1) with 3 neighbors becomes alive");

  // Rule 3 - Overpopulation
  it.todo("Rule 3 example: center cell (1,1) with 4 neighbors dies");

  // Blinker (oscillator) - integration of survival + reproduction + underpopulation
  it.todo("vertical blinker becomes horizontal -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");

  // Negative coordinates handling
  it.todo("handles negative coordinates -- blinker around origin oscillates correctly");
});

