export type Cell = [number, number];

const keyOf = ([x, y]: Cell): string => `${x},${y}`;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveKeys = new Set<string>(liveCells.map(keyOf));
  const neighborCounts = countNeighbors(liveCells);

  const survivors: Cell[] = [];
  for (const [key, { cell, count }] of neighborCounts) {
    const isAlive = liveKeys.has(key);
    if (count === 3 || (isAlive && count === 2)) {
      survivors.push(cell);
    }
  }
  return survivors;
}

function countNeighbors(liveCells: Cell[]): Map<string, { cell: Cell; count: number }> {
  const counts = new Map<string, { cell: Cell; count: number }>();
  for (const [x, y] of liveCells) {
    for (const [nx, ny] of neighborsOf(x, y)) {
      const key = keyOf([nx, ny]);
      const entry = counts.get(key);
      if (entry) {
        entry.count++;
      } else {
        counts.set(key, { cell: [nx, ny], count: 1 });
      }
    }
  }
  return counts;
}

function* neighborsOf(x: number, y: number): Generator<Cell> {
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx === 0 && dy === 0) continue;
      yield [x + dx, y + dy];
    }
  }
}

